#include <ctype.h>
#include <stdio.h>

int main(void) {
    const char text[] = "A7 z";
    for (size_t i = 0; text[i] != '\0'; ++i) {
        unsigned char ch = (unsigned char)text[i];
        if (isalpha(ch)) puts("letter");
        else if (isdigit(ch)) puts("digit");
        else if (isspace(ch)) puts("space");
    }
    return 0;
}

